Definition D_main_cells : list (Z * nat) :=
  [(0x561a0%Z, 8%nat); (0x76500%Z, 8%nat); (0x76560%Z, 8%nat); (0x76528%Z, 8%nat); (0x764f0%Z, 8%nat); (0x764e8%Z, 8%nat); (0x76298%Z, 8%nat); (0x762a8%Z, 8%nat); (0x762a0%Z, 8%nat); (0x76510%Z, 8%nat); (0x76518%Z, 8%nat); (0x56280%Z, 8%nat); (0x56268%Z, 8%nat); (0x561a8%Z, 8%nat); (0x764f8%Z, 1%nat); (0x561d0%Z, 4%nat); (0x561c8%Z, 4%nat); (0x56240%Z, 8%nat); (0x56220%Z, 8%nat); (0x561b0%Z, 8%nat); (0x561b8%Z, 8%nat); (0x561c0%Z, 8%nat); (0x764d8%Z, 4%nat); (0x764dc%Z, 4%nat); (0x764d9%Z, 1%nat); (0x56260%Z, 8%nat); (0x46120%Z, 1%nat)].

Definition range_disjoint_b (a : Z) (n : nat) (c : Z * nat) : bool :=
  ((a + Z.of_nat n <=? fst c) || (fst c + Z.of_nat (snd c) <=? a))%Z.

Definition D_main_missb (a : Z) (n : nat) : bool :=
  forallb (range_disjoint_b a n) D_main_cells && (0 <=? a)%Z && (a + Z.of_nat n <=? 0x77000)%Z.

(* [comment removed for export] *)
Definition djw (P : Prop) : Prop := P.

Section VP1. Context {fx : FPState}.   (* [comment removed for export] *)
Lemma range_disjoint_djw : forall a n c,
  range_disjoint_b a n c = true ->
  djw (a + Z.of_nat n <= fst c \/ fst c + Z.of_nat (snd c) <= a)%Z.
Proof.
